import{_ as c,r as t,o as i,c as r,e as p,a as n,s as e,d as s}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Плагины - October CMS - 3.x","titleTemplate":false,"description":"Основа для добавления новых функций в CMS путём её расширения.","frontmatter":{"subtitle":"Основа для добавления новых функций в CMS путём её расширения."},"headers":[{"level":3,"title":"Структура директории","slug":"структура-директории","link":"#структура-директории","children":[]},{"level":3,"title":"Пространства имён плагинов","slug":"пространства-имен-плагинов","link":"#пространства-имен-плагинов","children":[]},{"level":2,"title":"Файл регистрации","slug":"фаил-регистрации","link":"#фаил-регистрации","children":[{"level":3,"title":"Базовая информация о плагине","slug":"базовая-информация-о-плагине","link":"#базовая-информация-о-плагине","children":[]}]},{"level":2,"title":"Загрузка и инициализация","slug":"загрузка-и-инициализация","link":"#загрузка-и-инициализация","children":[]},{"level":2,"title":"Определение зависимостей","slug":"определение-зависимостеи","link":"#определение-зависимостеи","children":[]},{"level":2,"title":"История версий","slug":"история-версии","link":"#история-версии","children":[{"level":3,"title":"Зависимости плагинов","slug":"зависимости-плагинов","link":"#зависимости-плагинов","children":[]}]},{"level":2,"title":"Файл версий плагина","slug":"фаил-версии-плагина","link":"#фаил-версии-плагина","children":[{"level":3,"title":"Важные обновления","slug":"важные-обновления","link":"#важные-обновления","children":[]},{"level":3,"title":"Файлы миграций и заполнения","slug":"фаилы-миграции-и-заполнения","link":"#фаилы-миграции-и-заполнения","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/extend/system/plugins.md","filePath":"3.x/ru/extend/system/plugins.md"}'),u={name:"3.x/ru/extend/system/plugins.md"};function d(k,a,g,h,m,f){const o=t("pre-heading"),l=t("post-heading");return i(),r("div",null,[p(o),a[0]||(a[0]=n("h1",null,"Плагины",-1)),p(l),a[1]||(a[1]=e(`<div class="custom-block aside"><p>Плагины идентифицируются уникальным кодом, например, плагин <code>Acme.Blog</code> находится в директории <strong>plugins/acme/blog</strong>.</p></div><p>В этой статье описываются плагины и их функции регистрации. Процесс регистрации позволяет плагинам объявлять свои функции, такие как CMS-компоненты или навигацию и страницы панели управления. Вот некоторые примеры того, что может делать плагин.</p><ol><li>Создавать структуры таблиц базы данных и начальные данные.</li><li>Определять <a href="./../cms-components.html">CMS-компоненты</a>.</li><li>Определять <a href="./../backend/permissions.html">пользовательские разрешения</a>.</li><li>Добавлять <a href="./../settings/settings.html">страницы настроек</a>, <a href="./../backend/navigation.html">элементы навигации</a>, <a href="./../lists/list-controller.html">списки</a> и <a href="./../forms/form-controller.html">формы</a>.</li><li>Изменять <a href="./../extending.html">функциональность ядра или других плагинов</a>.</li><li>Предоставлять классы, <a href="./../system/controllers.html">контроллеры панели управления</a>, представления, ресурсы и другие файлы.</li></ol><h3 id="структура-директории"><a href="#структура-директории" class="header-anchor">#</a> Структура директории</h3><p>Плагины находятся в директории <strong>plugins</strong> директории приложения. Пример структуры директории плагина приведён ниже.</p><pre class="dir-container"><code><p>├── <code>plugins</code>
|   └── acme  <em>← Имя автора</em>
|       └── blog  <em>← Имя плагина</em>
|           ├── classes
|           ├── components
|           ├── controllers
|           ├── models
|           ├── updates
|           └── Plugin.php  <em>← Файл регистрации</em></p>
</code></pre><p>Не все директории плагина обязательны. Единственный обязательный файл — <strong>Plugin.php</strong>, описанный ниже. Если ваш плагин предоставляет только один компонент, структура директории плагина может быть гораздо проще, например:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>components</code>
|           └── Plugin.php</p>
</code></pre><h3 id="пространства-имен-плагинов"><a href="#пространства-имен-плагинов" class="header-anchor">#</a> Пространства имён плагинов</h3>`,9)),a[2]||(a[2]=n("p",null,[s("Пространства имён плагинов необходимы, особенно если вы планируете публиковать плагины на "),n("a",{href:"https://octobercms.com/plugins",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("маркетплейсе October CMS"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(". При регистрации в качестве автора на маркетплейсе вам будет предложено указать код автора, который должен использоваться как корневое пространство имён для всех ваших плагинов. Код автора можно указать только один раз при регистрации. Код автора по умолчанию, предлагаемый маркетплейсом, состоит из имени и фамилии автора: JohnSmith. Код нельзя изменить после регистрации. Все пространства имён ваших плагинов должны быть определены под корневым пространством имён, например "),n("code",null,"JohnSmith\\Blog"),s(".")],-1)),a[3]||(a[3]=e(`<h2 id="фаил-регистрации"><a href="#фаил-регистрации" class="header-anchor">#</a> Файл регистрации</h2><p>Команда <code>create:plugin</code> генерирует папку плагина и базовые файлы. Первый аргумент указывает имя автора и плагина.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:plugin Acme.Blog
</code></pre></div><p>Файл <strong>Plugin.php</strong>, называемый файлом регистрации плагина, является скриптом инициализации, объявляющим основные функции и информацию плагина. Файлы регистрации могут предоставлять следующее:</p><ol><li>Информацию о плагине, его название и автора.</li><li>Методы регистрации для расширения CMS.</li></ol><p>Скрипты регистрации должны использовать пространство имён плагина. Скрипт регистрации должен определять класс с именем <code>Plugin</code>, наследующий класс <code>System\\Classes\\PluginBase</code>. Единственный обязательный метод класса регистрации плагина — <code>pluginDetails</code>. Пример файла регистрации плагина приведён ниже.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">pluginDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Plugin&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Provides some really cool blog features.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ACME Corporation&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-leaf&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerComponents</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;blogPost&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="базовая-информация-о-плагине"><a href="#базовая-информация-о-плагине" class="header-anchor">#</a> Базовая информация о плагине</h3><p>Метод <code>pluginDetails</code> является обязательным методом класса регистрации плагина. Он должен возвращать массив, содержащий следующие ключи:</p><div class="table"><table tabindex="0"><thead><tr><th>Ключ</th><th>Описание</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>название плагина, обязательно.</td></tr><tr><td><strong>description</strong></td><td>описание плагина, обязательно.</td></tr><tr><td><strong>author</strong></td><td>имя автора плагина, обязательно.</td></tr><tr><td><strong>icon</strong></td><td>имя иконки плагина. Полный список доступных иконок можно найти в <a href="./../../element/available-icons.html">документации по доступным иконкам</a>. Любые имена иконок, предоставляемые этим шрифтом, являются допустимыми, например <strong>icon-glass</strong>, <strong>icon-music</strong>, необязательно.</td></tr><tr><td><strong>iconSvg</strong></td><td>SVG-иконка, используемая вместо стандартной иконки. SVG-иконка должна быть прямоугольной и может поддерживать цвета, необязательно.</td></tr><tr><td><strong>homepage</strong></td><td>ссылка на веб-сайт автора, необязательно.</td></tr><tr><td><strong>hint</strong></td><td>более короткий код, используемый для <a href="./controllers.html">маршрутизации URL контроллеров</a> в панели управления, необязательно.</td></tr></tbody></table></div><h2 id="загрузка-и-инициализация"><a href="#загрузка-и-инициализация" class="header-anchor">#</a> Загрузка и инициализация</h2><p>Файлы регистрации плагинов могут содержать два метода <code>boot</code> и <code>register</code>. С помощью этих методов вы можете делать всё что угодно, например регистрировать маршруты или подключать обработчики событий.</p><p>Метод <code>register</code> вызывается сразу при регистрации плагина. Метод <code>boot</code> вызывается непосредственно перед маршрутизацией запроса. Поэтому, если ваши действия зависят от другого плагина, используйте метод boot. Например, внутри метода <code>boot</code> можно расширять модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">hasOne</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Author</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Метод <code>boot</code> является необязательным, и его отсутствие улучшает производительность. Кроме того, только метод <code>boot</code> поддерживает внедрение зависимостей через контейнер приложения.</p></div><p>Плагины также могут предоставлять файл <strong>init.php</strong>, содержащий пользовательскую логику инициализации. Ниже приведён пример содержимого.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    <span class="token comment">// Logic when the request starts, after routes are registered</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    <span class="token comment">// Logic the request has finished, after the response is sent</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="определение-зависимостеи"><a href="#определение-зависимостеи" class="header-anchor">#</a> Определение зависимостей</h2><p>Плагин может зависеть от других плагинов, определив свойство <code>$require</code> в файле регистрации плагина. Свойство должно содержать массив имён плагинов, которые считаются зависимостями. Плагин, зависящий от плагина <strong>Acme.User</strong>, может объявить эту зависимость следующим образом:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array require these plugins
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$require</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;Acme.User&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Определения зависимостей влияют на работу плагина и на то, как процесс обновления применяет миграции. Процесс установки попытается установить все зависимости автоматически, однако если плагин обнаружен в системе без каких-либо своих зависимостей, он будет отключён для предотвращения системных ошибок.</p><p>Определения зависимостей могут быть сложными, но следует избегать циклических ссылок. Граф зависимостей всегда должен быть направленным, а циклическая зависимость считается ошибкой проектирования.</p><h2 id="история-версии"><a href="#история-версии" class="header-anchor">#</a> История версий</h2><p>Хорошей практикой для плагинов является ведение журнала изменений, документирующего любые изменения или улучшения в коде. Помимо написания заметок об изменениях, этот процесс обладает полезной возможностью выполнять <a href="./../database/structure.html">файлы миграций и заполнения</a> в правильном порядке.</p><p>Журнал изменений хранится в YAML-файле <code>version.yaml</code> внутри директории <strong>updates</strong> плагина, который соседствует с файлами миграций и заполнения. Этот пример показывает типичную структуру директории обновлений плагина:</p><pre class="dir-container"><code><p>├── plugins
|   └── author
|       └── myplugin
|           ├── <code>updates</code>
|           |   ├── <code>version.yaml</code>  <em>← Файл версий</em>
|           |   ├── create_tables.php  <em>← Скрипт базы данных</em>
|           |   ├── seed_the_database.php
|           |   └── create_another_table.php
|           └── Plugin.php</p>
</code></pre><h3 id="зависимости-плагинов"><a href="#зависимости-плагинов" class="header-anchor">#</a> Зависимости плагинов</h3><p>Обновления применяются в определённом порядке, основанном на зависимостях, определённых в файле регистрации плагина. Зависимые плагины не будут обновляться, пока все их зависимости не будут обновлены первыми.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$require</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;Acme.User&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В приведённом выше примере плагин <strong>Acme.Blog</strong> не будет обновлён, пока плагин <strong>Acme.User</strong> не будет полностью обновлён.</p><h2 id="фаил-версии-плагина"><a href="#фаил-версии-плагина" class="header-anchor">#</a> Файл версий плагина</h2>`,31)),a[4]||(a[4]=n("p",null,[s("Файл "),n("strong",null,"version.yaml"),s(", называемый файлом версий плагина, содержит комментарии к версиям и ссылается на скрипты базы данных в правильном порядке. Пожалуйста, прочитайте статью "),n("a",{href:"./../database/structure.html"},"Структура базы данных"),s(" для получения информации о файлах миграций. Этот файл обязателен, если вы собираетесь отправить плагин на "),n("a",{href:"https://octobercms.com/help/site/marketplace",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("маркетплейс"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(". Вот пример файла версий плагина.")],-1)),a[5]||(a[5]=e(`<div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v1.0.1</span><span class="token punctuation">:</span> First version
<span class="token key atrule">v1.0.2</span><span class="token punctuation">:</span> Second version
<span class="token key atrule">v1.0.3</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> Update with a migration and seed
    <span class="token punctuation">-</span> create_tables.php
    <span class="token punctuation">-</span> seed_the_database.php
<span class="token key atrule">v2.0.0</span><span class="token punctuation">:</span> Important update
<span class="token key atrule">v2.0.1</span><span class="token punctuation">:</span> Latest version
</code></pre></div><div class="custom-block tip"><p>Файл <code>version.yaml</code> должен всегда использовать первую строку для текстового обновления, описывающего изменения, а оставшиеся строки — для скриптов обновления. Для более подробных обновлений рассмотрите использование отдельного файла журнала изменений.</p></div><p>Как видно выше, должен быть ключ, представляющий номер версии, за которым следует сообщение обновления — строка или массив, содержащий сообщения обновления. Для обновлений, ссылающихся на файлы миграций или заполнения, строки с именами файлов скриптов могут располагаться в любой позиции. Пример комментария без связанных файлов обновления.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v1.0.1</span><span class="token punctuation">:</span> A single comment that uses no update scripts.
</code></pre></div><h3 id="важные-обновления"><a href="#важные-обновления" class="header-anchor">#</a> Важные обновления</h3><p>Иногда плагину необходимо внести изменения, которые сломают сайты, уже использующие плагин. Чтобы предотвратить автоматическое развёртывание изменений, следует увеличить <strong>мажорный</strong> сегмент строки версии (<code>major.minor.patch</code>). Пример комментария важного обновления приведён ниже.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v2.1.0</span><span class="token punctuation">:</span> This is an important update from v1 that contains breaking changes.
</code></pre></div><p>При тегировании новой версии <code>v2</code> с версии <code>v1</code> изменения не развёртываются в рамках обычного обновления. Пользователь должен установить плагин заново, чтобы получить последнюю версию через Composer.</p><h3 id="фаилы-миграции-и-заполнения"><a href="#фаилы-миграции-и-заполнения" class="header-anchor">#</a> Файлы миграций и заполнения</h3><p>Как было описано ранее, обновления также определяют, когда должны применяться <a href="./../database/structure.html">файлы миграций и заполнения</a>. Строка обновления с комментарием и обновлениями:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v1.1.1</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> This update will execute the two scripts below.
    <span class="token punctuation">-</span> some_upgrade_file.php
    <span class="token punctuation">-</span> some_seeding_file.php
</code></pre></div><p>Имя файла обновления должно использовать <em>snake_case</em>, а содержащийся PHP-класс — <em>CamelCase</em>. Для файла с именем <strong>some_upgrade_file.php</strong> соответствующий класс будет <code>SomeUpgradeFile</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Updates</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Schema</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>Migration</span><span class="token punctuation">;</span>

<span class="token comment">/**
 * some_upgrade_file.php
 */</span>
<span class="token keyword">class</span> <span class="token class-name-definition class-name">SomeUpgradeFile</span> <span class="token keyword">extends</span> <span class="token class-name">Migration</span>
<span class="token punctuation">{</span>
    <span class="token comment">///</span>
<span class="token punctuation">}</span>
</span></code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../database/structure.html">Миграции и заполнение базы данных</a></li></ul></div>`,15))])}const b=c(u,[["render",d]]);export{y as __pageData,b as default};
